package com.lmspilot.operations.domain; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; @Entity @Table(name="operation_schedules",indexes=@Index(name="idx_operation_schedule_due",columnList="enabled,next_run_at")) public class OperationScheduleEntity{@Id private UUID id=UUID.randomUUID();@Column(nullable=false,length=180)private String name="";@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private OperationType operationType=OperationType.BACKUP;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private OperationScheduleFrequency frequency=OperationScheduleFrequency.DAILY;@Column(name="day_of_week")private Integer dayOfWeek;@Column(name="hour_utc",nullable=false)private int hourUtc;@Column(nullable=false,columnDefinition="text")private String parametersJson="{}";@Column(nullable=false)private boolean enabled=true;@Column(name="next_run_at",nullable=false)private Instant nextRunAt=Instant.now();@Column(name="created_by",nullable=false)private UUID createdBy;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false)private Instant updatedAt=Instant.now();@Version private long version;public OperationScheduleEntity(){}public OperationScheduleEntity(String n,OperationType t,OperationScheduleFrequency f,Integer d,int h,String p,boolean e,Instant next,UUID by){name=n;operationType=t;frequency=f;dayOfWeek=d;hourUtc=h;parametersJson=p;enabled=e;nextRunAt=next;createdBy=by;}public UUID getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public OperationType getOperationType(){return operationType;}public void setOperationType(OperationType v){operationType=v;}public OperationScheduleFrequency getFrequency(){return frequency;}public void setFrequency(OperationScheduleFrequency v){frequency=v;}public Integer getDayOfWeek(){return dayOfWeek;}public void setDayOfWeek(Integer v){dayOfWeek=v;}public int getHourUtc(){return hourUtc;}public void setHourUtc(int v){hourUtc=v;}public String getParametersJson(){return parametersJson;}public void setParametersJson(String v){parametersJson=v;}public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public Instant getNextRunAt(){return nextRunAt;}public void setNextRunAt(Instant v){nextRunAt=v;}public UUID getCreatedBy(){return createdBy;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public void setUpdatedAt(Instant v){updatedAt=v;}}
